import React, { useState } from "react";

function RegisterForm({ onRegisterSuccess, goToLogin }) {
  const [email, setEmail] = useState("");
  const [mobile, setMobile] = useState("");
  const [password, setPassword] = useState("");
  const [name, setName] = useState("");
  const [error, setError] = useState("");
  const [success, setSuccess] = useState("");
  const [loading, setLoading] = useState(false);

  const handleRegister = async () => {
    setError("");
    setSuccess("");
    setLoading(true);
    try {
      const response = await fetch("http://localhost:8080/auth/register", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ email, mobile, password, name }),
      });

      if (!response.ok) {
        const errMsg = await response.text();
        throw new Error(errMsg || "Registration failed");
      }

      setSuccess("✅ Registration successful. Please login.");
      setEmail("");
      setMobile("");
      setPassword("");
      setName("");

      setTimeout(() => {
        onRegisterSuccess(); // Optional: auto-redirect after delay
      }, 1500);
    } catch (err) {
      setError(err.message || "Registration failed");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div style={styles.container}>
      <form
        onSubmit={(e) => {
          e.preventDefault();
          handleRegister();
        }}
        style={styles.form}
      >
        <h1 style={styles.title}>Create Account</h1>
        <p style={styles.subtitle}>Start your journey with us</p>

        <input
          type="text"
          placeholder="Full Name"
          value={name}
          onChange={(e) => setName(e.target.value)}
          required
          style={styles.input}
        />

        <input
          type="email"
          placeholder="Email Address"
          value={email}
          onChange={(e) => setEmail(e.target.value)}
          required
          style={styles.input}
        />

        <input
          type="tel"
          placeholder="Mobile Number"
          value={mobile}
          onChange={(e) => setMobile(e.target.value)}
          required
          style={styles.input}
        />

        <input
          type="password"
          placeholder="Password"
          value={password}
          onChange={(e) => setPassword(e.target.value)}
          required
          style={styles.input}
        />

        <button type="submit" style={styles.button} disabled={loading}>
          {loading ? "Registering..." : "Register"}
        </button>

        {error && <p style={styles.error}>{error}</p>}
        {success && <p style={styles.success}>{success}</p>}

        <p style={styles.switchText}>
          Already have an account?{" "}
          <span onClick={goToLogin} style={styles.link}>
            Login here
          </span>
        </p>
      </form>
    </div>
  );
}

const styles = {
  container: {
    minHeight: "100vh",
    display: "flex",
    justifyContent: "center",
    alignItems: "center",
    background: "#f7f9fc",
    fontFamily: "'Segoe UI', Tahoma, Geneva, Verdana, sans-serif",
    padding: "20px",
  },
  form: {
    backgroundColor: "#ffffff",
    padding: "36px",
    borderRadius: "18px",
    boxShadow: "0 8px 30px rgba(0, 0, 0, 0.1)",
    maxWidth: "420px",
    width: "100%",
  },
  title: {
    fontSize: "28px",
    marginBottom: "8px",
    fontWeight: "700",
    color: "#111",
    textAlign: "center",
  },
  subtitle: {
    fontSize: "14px",
    marginBottom: "24px",
    textAlign: "center",
    color: "#666",
  },
  input: {
    width: "100%",
    padding: "14px",
    marginBottom: "16px",
    borderRadius: "8px",
    border: "1px solid #ddd",
    fontSize: "15px",
    transition: "0.2s border",
  },
  button: {
    width: "100%",
    padding: "14px",
    backgroundColor: "#007bff",
    color: "white",
    fontWeight: "600",
    border: "none",
    borderRadius: "8px",
    fontSize: "16px",
    cursor: "pointer",
  },
  error: {
    marginTop: "16px",
    color: "#dc3545",
    textAlign: "center",
    fontSize: "14px",
  },
  success: {
    marginTop: "16px",
    color: "#28a745",
    textAlign: "center",
    fontSize: "14px",
  },
  switchText: {
    marginTop: "20px",
    fontSize: "14px",
    textAlign: "center",
    color: "#555",
  },
  link: {
    color: "#007bff",
    cursor: "pointer",
    fontWeight: "600",
    textDecoration: "underline",
    marginLeft: "5px",
  },
};

export default RegisterForm;
